import{_ as a,c as t,a0 as o,o as r}from"./chunks/framework.BGabeMLJ.js";const p=JSON.parse('{"title":"Demo Instance","description":"","frontmatter":{},"headers":[],"relativePath":"guide/user/demo.md","filePath":"guide/user/demo.md"}'),n={name:"guide/user/demo.md"};function i(s,e,d,l,h,c){return r(),t("div",null,e[0]||(e[0]=[o('<h1 id="demo-instance" tabindex="-1">Demo Instance <a class="header-anchor" href="#demo-instance" aria-label="Permalink to &quot;Demo Instance&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This guide explains how analysts can execute analyses on FLAME. It serves as a starting point and provides an overview of the complete workflow, linking to the detailed documentation for each individual step.</p><p>Two common use cases are covered:</p><ul><li>Running the existing demo analysis <a href="https://github.com/PrivateAIM/Herrsching2026" target="_blank" rel="noreferrer">HALTA</a> to become familiar with the platform and verify that the environment is working correctly.</li><li>Developing and executing your own analysis, using either the provided demo code as a starting point or your own analysis implementation.</li></ul><h3 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><p>This guide covers the complete workflow required to prepare and execute an analysis on the demo instance. It explains how to:</p><ul><li>create and configure a project</li><li>upload data and make it available in a data store</li><li>connect the data store to a FLAME node</li><li>execute an existing demo analysis</li><li>develop and run your own analysis</li></ul><p>Where appropriate, references to dedicated documentation pages are provided for more detailed explanations of individual steps.</p><h3 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h3><p>After completing this guide, you should be able to make data available for analysis and successfully execute either a provided demo analysis or your own analysis on the FLAME platform.</p><h2 id="preparation" tabindex="-1">Preparation <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Preparation&quot;">​</a></h2><h3 id="_1-create-a-project-in-the-hub" tabindex="-1">1. Create a Project in the Hub <a class="header-anchor" href="#_1-create-a-project-in-the-hub" aria-label="Permalink to &quot;1. Create a Project in the Hub&quot;">​</a></h3><p>To run an analysis, a project must first be created in the Hub. A project defines the scope of the analysis, including the target nodes, the requested data, and the images to be used. Creating a project is described in detail <a href="./project.html">here</a>.</p><h3 id="_2-upload-data-to-the-data-store" tabindex="-1">2. Upload Data to the Data Store <a class="header-anchor" href="#_2-upload-data-to-the-data-store" aria-label="Permalink to &quot;2. Upload Data to the Data Store&quot;">​</a></h3><p>To run an analysis on data, the data first needs to be made available in the corresponding node&#39;s data store. Each node has its own data store, in which a dedicated bucket can be created for each project. The required data can then be uploaded to the project-specific bucket.</p><p>The setup of a data store bucket is described in detail <a href="./../admin/bucket-setup-for-data-store.html">here</a>.</p><h4 id="demo-data" tabindex="-1">Demo Data <a class="header-anchor" href="#demo-data" aria-label="Permalink to &quot;Demo Data&quot;">​</a></h4><p>The data for the existing demo analysis <a href="https://github.com/PrivateAIM/Herrsching2026" target="_blank" rel="noreferrer">HALTA</a> can be found <a href="https://github.com/PrivateAIM/Herrsching2026/blob/master/data/node1/synthetic_eucare_1_labeled.csv" target="_blank" rel="noreferrer">here for Node 1</a> and <a href="https://github.com/PrivateAIM/Herrsching2026/blob/master/data/node2/synthetic_eucare_2_labeled.csv" target="_blank" rel="noreferrer">here for Node 2</a>.</p><h4 id="synthetic-data" tabindex="-1">Synthetic Data <a class="header-anchor" href="#synthetic-data" aria-label="Permalink to &quot;Synthetic Data&quot;">​</a></h4><p>If you do not have access to real data, you can create your own synthetic dataset and use it to test your analysis.</p><h3 id="_3-connect-the-data-store-to-the-node" tabindex="-1">3. Connect the Data Store to the Node <a class="header-anchor" href="#_3-connect-the-data-store-to-the-node" aria-label="Permalink to &quot;3. Connect the Data Store to the Node&quot;">​</a></h3><p>To enable an analysis to access the required data, the data store must be connected to the corresponding node. The process of connecting a data store to a node is described in detail <a href="./../admin/data-store-management.html">here</a>.</p><h2 id="running-analyses" tabindex="-1">Running Analyses <a class="header-anchor" href="#running-analyses" aria-label="Permalink to &quot;Running Analyses&quot;">​</a></h2><p>Once the project has been created, the data uploaded to the data store, and the data store connected to the node, an analysis can be created within the project. Creating an analysis involves selecting the analysis code, the target nodes, and the entrypoint for the analysis, and is described in detail <a href="./analysis.html">here</a>.</p><h3 id="run-the-demo-analysis" tabindex="-1">Run the Demo Analysis <a class="header-anchor" href="#run-the-demo-analysis" aria-label="Permalink to &quot;Run the Demo Analysis&quot;">​</a></h3><p>The script for the existing demo analysis <a href="https://github.com/PrivateAIM/Herrsching2026" target="_blank" rel="noreferrer">HALTA</a> is available <a href="https://github.com/PrivateAIM/Herrsching2026/blob/master/analysis/analysis.py" target="_blank" rel="noreferrer">on GitHub</a> and can be used to run the demo analysis on the previously uploaded demo data.</p><h3 id="create-your-own-analysis" tabindex="-1">Create Your Own Analysis <a class="header-anchor" href="#create-your-own-analysis" aria-label="Permalink to &quot;Create Your Own Analysis&quot;">​</a></h3><p>See <a href="./analysis-coding.html">Analysis Coding</a> for instructions on developing your own analysis.</p>',29)]))}const m=a(n,[["render",i]]);export{p as __pageData,m as default};
